import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.rfIdp5fP.js";const k=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),n={name:"guide/quickstart.md"};function l(o,a,r,h,p,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Build the toolkit, run one generator against the bundled example ontology, and look at what came out. About five minutes, most of it the first Maven build.</p><h2 id="_1-build" tabindex="-1">1. Build <a class="header-anchor" href="#_1-build" aria-label="Permalink to &quot;1. Build&quot;">​</a></h2><p>From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mvnw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>This produces <code>target/oddtoolkit.jar</code>. See <a href="./installation">Installation</a> for prerequisites and Windows commands.</p><p>Check that it runs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="_2-know-your-inputs" tabindex="-1">2. Know your inputs <a class="header-anchor" href="#_2-know-your-inputs" aria-label="Permalink to &quot;2. Know your inputs&quot;">​</a></h2><p>The repository ships a complete working example, the RIE-IEPR ontology:</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>docs/examples/riepr/ontology/ns/riepr/riepr.ttl</code></td><td>The ontology</td></tr><tr><td><code>docs/examples/riepr/ontology/id/concept/riepr/riepr.ttl</code></td><td>The SKOS concept scheme</td></tr><tr><td><code>src/test/resources/application.yml</code></td><td>A ready-made configuration that points at both</td></tr></tbody></table><p>You always need a configuration file. The ontology and concept-scheme paths have no defaults, so a run without <code>--config-file</code> — and without both <code>--ontology-file</code> and <code>--concepts-file</code> — fails while loading the ontology. Start from <code>src/test/resources/application.yml</code> and adapt it later.</p><h2 id="_3-run-a-generator" tabindex="-1">3. Run a generator <a class="header-anchor" href="#_3-run-a-generator" aria-label="Permalink to &quot;3. Run a generator&quot;">​</a></h2><p>Generate the Mermaid class diagram:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=class-diagram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span></span></code></pre></div><p>The first run reaches out to the network: the <code>ontology-extract-external</code> adapter fetches the vocabularies the ontology imports (results are cached under <code>target/test-cache/external</code>), and PNG export downloads a Playwright browser. Both are optional — see below if you are offline.</p><h2 id="_4-look-at-the-output" tabindex="-1">4. Look at the output <a class="header-anchor" href="#_4-look-at-the-output" aria-label="Permalink to &quot;4. Look at the output&quot;">​</a></h2><p>The configuration writes everything under <code>target/test-cache/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/test-cache/class-diagram/</span></span></code></pre></div><p>You get <code>class-diagram.mmd</code>, and <code>class-diagram.png</code> if PNG export succeeded. The <code>.mmd</code> file is plain text — open it, or paste it into any Mermaid renderer.</p><h2 id="_5-try-the-others" tabindex="-1">5. Try the others <a class="header-anchor" href="#_5-try-the-others" aria-label="Permalink to &quot;5. Try the others&quot;">​</a></h2><p>Same command, different generator name:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SQL schema -&gt; target/test-cache/sql/schema.sql</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generator=sql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-file=src/test/resources/application.yml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Java model classes -&gt; target/test-cache/java/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generator=java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-file=src/test/resources/application.yml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Everything at once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generator=all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-file=src/test/resources/application.yml</span></span></code></pre></div><p><code>--generator=all</code> runs all ten generators in one JVM. The full list is in the <a href="./cli">CLI reference</a>, and <a href="./generators">Generators</a> explains each one.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>Turn up the logging — <code>ODD_LOG_LEVEL</code> is the only environment variable the toolkit reads:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ODD_LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEBUG</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/oddtoolkit.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --generator=class-diagram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file=src/test/resources/application.yml</span></span></code></pre></div><p>Working offline, or want to skip the browser download? Copy the configuration and disable the two network-dependent parts:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">generators</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  diagram-generator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    export-png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">adapters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ontology-extract-external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>Disabling <code>ontology-extract-external</code> means imported external vocabularies are not resolved, so the generated output will be thinner. See <a href="./adapters">Adapters</a> for what each adapter contributes.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./cli">CLI Reference</a> — every option, with its failure modes</li><li><a href="./configuration">Configuration Reference</a> — the <code>ontology</code>, <code>generators</code> and <code>adapters</code> sections</li><li><a href="./generators">Generators</a> — what each generator emits and how to configure it</li><li><a href="./examples">Generated Examples</a> — the output this ontology produces</li></ul>`,32)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
